import{z as l,x as i,o as B,c as s,q as e,j as t,D as a,d as r,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"组合效应与监管","description":"","frontmatter":{"title":"组合效应与监管","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ot-portfolio-regulation.md","filePath":"quant/ot-portfolio-regulation.md","lastUpdated":1791413859000}'),C={name:"quant/ot-portfolio-regulation.md"};function d(p,E,h,u,c,f){const A=i("Mermaid");return B(),s("div",null,[E[2]||(E[2]=e('<h1 id="组合效应与监管" tabindex="-1">组合效应与监管 <a class="header-anchor" href="#组合效应与监管" aria-label="Permalink to &quot;组合效应与监管&quot;">​</a></h1><div class="epigraph"><p>单笔合规不等于组合合规：监管的对象从来不是一份确认书，是账本、客户群体与市场上同步运行的对冲规则。</p><footer>—— 据 BCBS-IOSCO 保证金要求框架（2015，分阶段实施至 2022）与中国证券业协会《证券公司场外期权业务管理办法》（2020）整理</footer></div><p><a href="/quant/ot-exchange-hedge-otc">上一课</a>把场内对冲的残差分桶认领。本课把视角拉到最高一层：产品条款之外，组合与制度如何改写风险。三条线：发行台账本的组合效应、客户群体的组合效应、监管对两者的结构化要求。前七课的产出——谱系表、障碍地图、净额集、残差桶——在此都是监管口径的输入。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>账本内两笔头寸风险对消，监管是否承认，取决于它们是否在同一法律净额集——<a href="/quant/ot-isda-documentation">文档体系</a>立的构造直接变成资本与暴露的计算单位。客户侧的效应更隐蔽：同一个月发行的两百只雪球，敲入线挤在同一指数区间，单只看分散良好，组合看是同一事件的重仓——客户的集中度、发行台的 gamma 峰、市场上同步的对冲流量，三层是同一个结构的三种投影，<a href="/quant/snowball-dealer-hedging">对冲商的堆积</a>写的市场反馈是它的第三层。缺口是：组合效应既不被单笔检查捕捉，也不被逐产品的适当性检查捕捉。</p><p><span class="marginnote">「法律净额集」就是用一份主协议把多笔交易绑成一个计算单位，盈亏先两两对消、再算暴露与资本。可以把它想象成同一个钱包里的收支可以互相抵扣，而两个钱包之间的欠条不能拿来抵——所以跨对手、跨产品的集中度永远进不了净额。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>监管四层各落一个动作。报告层：场外交易逐笔报送集中结算与统计系统，字段与确认书一致，报送迟漏本身是合规事件。保证金与清算层：非集中清算的双边组合按 BCBS-IOSCO 框架交换变动与初始保证金——分阶段实施到 2022 年 9 月覆盖到日均名义超 80 亿欧元的机构集团；可清算产品强制集中清算，双边暴露换成对 CCP 的暴露，口径沿 <a href="/quant/ccp-clearing">CCP 清算</a>。资本层：SA-CCR 把净额集、抵押与久期折成交易对手信用风险暴露，资本成本反过来改写报价——<a href="/quant/rc-regcap-pricing">监管资本下的定价</a>立的「资本写回报价」在结构化产品上同样生效。销售层：适当性管理把<a href="/quant/snowball-pricing">雪球定价课</a>的销售口径变成程序——产品风险评级、投资者匹配、双录与冷静期，中国场外期权的交易商与投资者分层沿《证券公司场外期权业务管理办法》。</p>',8)),(B(),t(o,null,{default:a(()=>[n(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOK%5B%22%E5%8F%91%E8%A1%8C%E5%8F%B0%E8%B4%A6%E6%9C%AC%EF%BC%9A%E5%87%80%E9%A2%9D%E9%9B%86%E4%B8%8E%E9%9A%9C%E7%A2%8D%E5%9C%B0%E5%9B%BE%22%5D%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%E5%B1%82%EF%BC%9A%E9%80%90%E7%AC%94%E6%8A%A5%E9%80%81%22%5D%0A%20%20BOOK%20--%3E%20MRG%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E5%B1%82%EF%BC%9A%E5%8F%8C%E8%BE%B9%20IM%20%E4%B8%8E%E9%9B%86%E4%B8%AD%E6%B8%85%E7%AE%97%22%5D%0A%20%20BOOK%20--%3E%20CAP%5B%22%E8%B5%84%E6%9C%AC%E5%B1%82%EF%BC%9ASA-CCR%20%E5%86%99%E5%9B%9E%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20CUST%5B%22%E5%AE%A2%E6%88%B7%E7%BB%84%E5%90%88%EF%BC%9A%E6%95%B2%E5%85%A5%E5%B8%A6%E9%9B%86%E4%B8%AD%E5%BA%A6%22%5D%20--%3E%20SUIT%5B%22%E9%94%80%E5%94%AE%E5%B1%82%EF%BC%9A%E9%80%82%E5%BD%93%E6%80%A7%E4%B8%8E%E4%BA%A7%E5%93%81%E8%AF%84%E7%BA%A7%22%5D%0A%20%20ALL%5B%22%E4%B8%89%E5%B1%82%E6%8A%95%E5%BD%B1%EF%BC%9A%E5%90%8C%E4%B8%80%E7%BB%93%E6%9E%84%22%5D%20--%3E%20LIM%5B%22%E9%9B%86%E4%B8%AD%E5%BA%A6%E4%B8%8E%E6%83%85%E6%99%AF%E9%99%90%E9%A2%9D%22%5D%0A%20%20REP%20--%3E%20ALL%0A%20%20MRG%20--%3E%20ALL%0A%20%20CAP%20--%3E%20ALL%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p><span class="marginnote">数字感受一下「敲入带集中」：两百只雪球每只名义 1000 万元，敲入线都设在指数下跌 20%–25% 的窄带里，组合就是 20 亿元名义同时押在同一个事件上——单只产品的风险评级与分散度检查完全照不出这 20 亿。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>监管盯组合的机制理由是系统性风险的载体：危机传导不靠单笔违约，靠同步规则的共振——保证金触发的同步抛售沿<a href="/quant/rc-collateral-funding">抵押与资金链</a>的折价螺旋，对冲触发的同步流量沿<a href="/quant/crowding-spiral">拥挤螺旋</a>。合规因此必须给组合留两个量：法律净额集内的可对消量（资本口径），与跨对手、跨产品的不可对消集中度（风险口径）；两者不许互相借用。限额把集中度写成情景：同一敲入带上的存续名义、触发时按<a href="/quant/ot-exchange-hedge-otc">对冲流量对深度</a>的冲击估计，挂进<a href="/quant/rk-limit-system">限额体系</a>。不这么做会错在哪：每只产品都通过了单笔适当性，敲入集中触发的那一周，发行台的对冲与客户的赎回同时到门口，监管与账本一起发现「组合」这个对象此前不存在。</p>',3)),(B(),t(o,null,{default:a(()=>[n(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRIG%5B%22%E5%90%8C%E4%B8%80%E6%95%B2%E5%85%A5%E5%B8%A6%E8%A2%AB%E9%9B%86%E4%B8%AD%E8%A7%A6%E5%8F%91%22%5D%20--%3E%20A%5B%22%E7%BA%BF%E4%B8%80%EF%BC%9A%E5%AE%A2%E6%88%B7%E8%B5%8E%E5%9B%9E%E9%9B%86%E4%B8%AD%E5%88%B0%E9%97%A8%E5%8F%A3%22%5D%0A%20%20TRIG%20--%3E%20B%5B%22%E7%BA%BF%E4%BA%8C%EF%BC%9A%E5%8F%91%E8%A1%8C%E5%8F%B0%20gamma%20%E5%AF%B9%E5%86%B2%E5%90%8C%E5%90%91%E6%B5%81%E9%87%8F%22%5D%0A%20%20TRIG%20--%3E%20C%5B%22%E7%BA%BF%E4%B8%89%EF%BC%9A%E4%BF%9D%E8%AF%81%E9%87%91%E8%BF%BD%E7%BC%B4%E5%BC%95%E8%87%B4%E6%8A%9B%E5%94%AE%22%5D%0A%20%20A%20--%3E%20RES%5B%22%E4%B8%89%E7%BA%BF%E5%85%B1%E6%8C%AF%EF%BC%9A%E5%B8%82%E5%9C%BA%E6%B7%B1%E5%BA%A6%E7%9E%AC%E6%97%B6%E6%9E%AF%E7%AB%AD%22%5D%0A%20%20B%20--%3E%20RES%0A%20%20C%20--%3E%20RES%0A%20%20RES%20--%3E%20LIM%5B%22%E6%83%85%E6%99%AF%E9%99%90%E9%A2%9D%EF%BC%9A%E5%AD%98%E7%BB%AD%E5%90%8D%E4%B9%89%E4%B8%8E%E5%86%B2%E5%87%BB%E9%A2%84%E4%BC%B0%E6%8C%82%E8%B4%A6%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">初学者容易以为每只产品都通过单笔适当性检查，组合就自动安全。实际上组合风险恰是单笔检查的盲区：监管要看的是「同一周有多少钱同时到门口」，这个量在任何一份单笔确认书或适当性文件里都不存在。</span></p><p><span class="marginnote">保证金规则的分阶段实施表本身就是一条风险时间线：新阶段生效日前后，过去双边免 IM 的组合一夜进入抵押品需求，合格的国债与现金被重新分配。制度日程要挂进压力测试日历，与观察日历同等对待。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写监管条文史，规则文本以现行有效的为准；跨境产品的法域冲突只在净额意见处点名。投资者保护的微观机制（双录、举证）属于销售管理专题。策略层面的台账与版本治理沿<a href="/quant/sl-registry">策略台账体系</a>与<a href="/quant/cn-compliance-map">中国市场合规红线</a>，不重复。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>组合效应有两层：账本内的法律对消与客户群的敲入带集中，单笔检查都测不到。</li><li>监管四层：报告、保证金与清算、资本、适当性；每层把前课的产出变成程序。</li><li>法律净额的可对消量与跨对手集中度分列，不许互相借用。</li><li>系统性风险的载体是同步规则：保证金、对冲、赎回三条共振线各挂情景限额。</li><li>出处：BCBS-IOSCO 保证金框架（2015–2022）；中国证券业协会《证券公司场外期权业务管理办法》（2020）；口径沿<a href="/quant/rc-collateral-funding">抵押与资金链</a>与<a href="/quant/rk-limit-system">限额体系</a>。</li></ul>',6))])}const D=l(C,[["render",d]]);export{_ as __pageData,D as default};
